commands.command:
set -eu
cat > /home/nodeapp/node-hello/server.js <<'ANTRIEB_SERVER'
const http = require('http');
const body = 'Hello, world!';

http.createServer((req, res) => {
  if (req.url === '/') {
    res.writeHead(200, {
      'Content-Type': 'text/plain',
      'Content-Length': Buffer.byteLength(body)
    });
    res.end(body);
    return;
  }
  res.writeHead(404, { 'Content-Length': '0' });
  res.end();
}).listen(8080, '0.0.0.0');
ANTRIEB_SERVER
cat > /home/nodeapp/node-hello/Containerfile <<'ANTRIEB_CONTAINERFILE'
FROM docker.io/library/node:22-alpine
WORKDIR /app
COPY server.js /app/server.js
EXPOSE 8080
USER node
CMD ["node", "/app/server.js"]
ANTRIEB_CONTAINERFILE
cat > /home/nodeapp/.config/systemd/user/node-hello.service <<'ANTRIEB_UNIT'
[Unit]
Description=Rootless Podman Node.js hello-world application
Wants=network-online.target
After=network-online.target

[Service]
Type=exec
Restart=always
RestartSec=3
TimeoutStopSec=30
ExecStart=/usr/bin/podman run --replace --name node-hello --pull=never --publish 0.0.0.0:8080:8080 localhost/node-hello:latest
ExecStop=/usr/bin/podman stop --ignore --time 10 node-hello
ExecStopPost=-/usr/bin/podman rm --force --ignore node-hello

[Install]
WantedBy=default.target
ANTRIEB_UNIT
chown -R nodeapp:nodeapp /home/nodeapp/node-hello /home/nodeapp/.config
chmod 0644 /home/nodeapp/node-hello/server.js /home/nodeapp/node-hello/Containerfile /home/nodeapp/.config/systemd/user/node-hello.service
printf 'files_created\n'
sed -n '1,80p' /home/nodeapp/.config/systemd/user/node-hello.service
